INSERT INTO feature VALUES('modules','modules','Modules',NULL,'implemented','ordinary',NULL,'A module groups member declarations, each reached through the module''s name. A data declaration in a module body is a member: its family is `M.Box` outside the module, its constructor `M.B` in a value and in a pattern and `M.Box.B` in a value, and each is bare inside it.','surface-lowering','corpus/model/modules/nullary-member.gandr corpus/model/modules/nat-add.gandr corpus/model/modules/data-member.gandr corpus/pathological/modules/data-member.gandr','corpus/ledger/features/modules.gandr',NULL);
